selector_to_html = {"a[href=\"#use-semantic-locators\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. Use Semantic Locators<a class=\"headerlink\" href=\"#use-semantic-locators\" title=\"Link to this heading\">#</a></h3><p>The generated code uses role-based locators when possible, which are more resilient:</p>", "a[href=\"#test-generation\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Test Generation<a class=\"headerlink\" href=\"#test-generation\" title=\"Link to this heading\">#</a></h1><p>Generate Playwright test code automatically as you interact with the browser.</p>", "a[href=\"#building-a-test-file\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Building a Test File<a class=\"headerlink\" href=\"#building-a-test-file\" title=\"Link to this heading\">#</a></h2><p>Collect the generated code into a Playwright test:</p>", "a[href=\"#best-practices\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Best Practices<a class=\"headerlink\" href=\"#best-practices\" title=\"Link to this heading\">#</a></h2><h3>1. Use Semantic Locators<a class=\"headerlink\" href=\"#use-semantic-locators\" title=\"Link to this heading\">#</a></h3><p>The generated code uses role-based locators when possible, which are more resilient:</p>", "a[href=\"#example-workflow\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Example Workflow<a class=\"headerlink\" href=\"#example-workflow\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#add-assertions-manually\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. Add Assertions Manually<a class=\"headerlink\" href=\"#add-assertions-manually\" title=\"Link to this heading\">#</a></h3><p>Generated code captures actions but not assertions. Add expectations in your test using one of the recommended matchers:</p>", "a[href=\"#how-it-works\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">How It Works<a class=\"headerlink\" href=\"#how-it-works\" title=\"Link to this heading\">#</a></h2><p>Every action you perform with <code class=\"docutils literal notranslate\"><span class=\"pre\">playwright-cli</span></code> generates corresponding Playwright TypeScript code.\nThis code appears in the output and can be copied directly into your test files.</p>", "a[href=\"#explore-before-recording\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. Explore Before Recording<a class=\"headerlink\" href=\"#explore-before-recording\" title=\"Link to this heading\">#</a></h3><p>Take snapshots to understand the page structure before recording actions:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
